TEST(PngDecode, DecodeExifAttachedToMetaRaw) {
  std::vector<uint8_t> buf;
  ASSERT_TRUE(png_test::load_png_file("png_exif.png", buf)) << "Run tests/data/png/generate.py";

  GIMG_Stream * s = nullptr;
  GIMG_Result r = gimg_stream_create_memory(buf.data(), buf.size(), &s);
  ASSERT_EQ(r, GIMG_OK);
  ASSERT_NE(s, nullptr);

  GIMG_Doc * doc = nullptr;
  r = gimg_doc_load(s, nullptr, nullptr, &doc);
  ASSERT_EQ(r, GIMG_OK);
  ASSERT_NE(doc, nullptr);

  GIMG_Meta_Raw * raw = gimg_doc_meta_raw(doc);
  ASSERT_NE(raw, nullptr) << "eXIf chunk should attach doc meta_raw";

  size_t size = 0;
  r = gimg_meta_raw_get(raw, "png", kPngChunk_eXIf, nullptr, &size);
  ASSERT_EQ(r, GIMG_OK);
  EXPECT_EQ(size, 6u) << "eXIf payload in generate.py is 6 bytes";

  std::vector<uint8_t> exif_buf(size);
  r = gimg_meta_raw_get(raw, "png", kPngChunk_eXIf, exif_buf.data(), &size);
  ASSERT_EQ(r, GIMG_OK);
  EXPECT_EQ(size, 6u);
  EXPECT_EQ(exif_buf[0], 0x00);
  EXPECT_EQ(exif_buf[5], 0x05);

  gimg_doc_destroy(doc);
  gimg_stream_destroy(s);
}

