// ---------------------------------------------------------------------------
// Sample depths below 8 bits, crossed with Adam7 interlacing.
//
// PNG 7.2 packs samples of depth 1, 2 and 4 several to a byte, MSB first, each
// scanline padded to a byte boundary. Adam7 (PNG 8.2) then splits the image
// into seven passes of independently padded scanlines. Pixel i of a pass row
// belongs at image column x_offset + i * x_step, which below 8 bits is a *bit*
// position; treating it as a byte position both corrupts memory and misplaces
// every sample. The fixtures come in interlaced and non-interlaced pairs built
// from one sample array by tests/data/png/generate.py, with the expected
// pixels in a .raw file computed from PNG 13.12's rescaling rule.
// ---------------------------------------------------------------------------

namespace {

struct SubByteCase {
  const char * base;  ///< Fixture stem, e.g. "png_gray1_32x8".
  uint32_t width;
  uint32_t height;
  bool palette;       ///< Palette decodes to RGBA8; grayscale to GRAY8.
};

const SubByteCase kSubByteCases[] = {
    {"png_gray1_32x8", 32, 8, false},
    {"png_gray2_32x8", 32, 8, false},
    {"png_gray4_32x8", 32, 8, false},
    {"png_pal1_32x8", 32, 8, true},
    {"png_pal2_32x8", 32, 8, true},
    {"png_pal4_32x8", 32, 8, true},
    {"png_gray1_33x9", 33, 9, false},
    {"png_gray2_33x9", 33, 9, false},
    {"png_gray4_33x9", 33, 9, false},
    {"png_pal1_33x9", 33, 9, true},
    {"png_pal2_33x9", 33, 9, true},
    {"png_pal4_33x9", 33, 9, true},
};

/** Decode a fixture by name. Caller destroys *out_raster, *out_doc, *out_s. */
::testing::AssertionResult DecodeFixture(const char * filename,
    GIMG_Stream ** out_s, GIMG_Doc ** out_doc, GIMG_Raster ** out_raster) {
  std::vector<uint8_t> buf;
  if (!png_test::load_png_file(filename, buf)) {
    return ::testing::AssertionFailure()
        << filename << " missing; run tests/data/png/generate.py";
  }
  GIMG_Stream * s = nullptr;
  if (gimg_stream_create_memory(buf.data(), buf.size(), &s) != GIMG_OK) {
    return ::testing::AssertionFailure() << "stream create failed";
  }
  GIMG_Doc * doc = nullptr;
  GIMG_Result r = gimg_doc_load(s, nullptr, nullptr, &doc);
  if (r != GIMG_OK) {
    gimg_stream_destroy(s);
    return ::testing::AssertionFailure()
        << "load " << filename << " failed: " << static_cast<int>(r);
  }
  GIMG_Raster * raster = nullptr;
  r = gimg_item_decode(gimg_doc_item(doc, 0), nullptr, &raster);
  if (r != GIMG_OK) {
    gimg_doc_destroy(doc);
    gimg_stream_destroy(s);
    return ::testing::AssertionFailure()
        << "decode " << filename << " failed: " << static_cast<int>(r);
  }
  *out_s = s;
  *out_doc = doc;
  *out_raster = raster;
  return ::testing::AssertionSuccess();
}

/** Copy a raster's pixels without stride padding. */
std::vector<uint8_t> RasterBytes(const GIMG_Raster * raster) {
  const GIMG_Pixel_Format * fmt = gimg_raster_format(raster);
  size_t bpp = gimg_raster_bytes_per_pixel(fmt);
  uint32_t w = gimg_raster_width(raster);
  uint32_t h = gimg_raster_height(raster);
  size_t stride = gimg_raster_stride_bytes(raster);
  const unsigned char * px =
      static_cast<const unsigned char *>(gimg_raster_pixels_const(raster));
  std::vector<uint8_t> out;
  out.reserve(static_cast<size_t>(w) * h * bpp);
  for (uint32_t y = 0; y < h; y++) {
    out.insert(out.end(), px + static_cast<size_t>(y) * stride,
        px + static_cast<size_t>(y) * stride + static_cast<size_t>(w) * bpp);
  }
  return out;
}

} // namespace

TEST(PngDecode, SubByteDepthsDecodeToTheSamplesTheSpecScalesThemTo) {
  for (const SubByteCase & c : kSubByteCases) {
    std::vector<uint8_t> expected;
    ASSERT_TRUE(png_test::load_png_file(
        (std::string(c.base) + ".raw").c_str(), expected))
        << c.base << ".raw missing; run tests/data/png/generate.py";

    GIMG_Stream * s = nullptr;
    GIMG_Doc * doc = nullptr;
    GIMG_Raster * raster = nullptr;
    ASSERT_TRUE(DecodeFixture(
        (std::string(c.base) + ".png").c_str(), &s, &doc, &raster));

    EXPECT_EQ(gimg_raster_width(raster), c.width) << c.base;
    EXPECT_EQ(gimg_raster_height(raster), c.height) << c.base;
    const GIMG_Pixel_Format * fmt = gimg_raster_format(raster);
    // PNG 4.5.5: a palette entry is RGB, so an indexed image decodes to
    // color; a grayscale image of any depth below 8 rescales to GRAY8.
    EXPECT_EQ(fmt->channel_model,
        c.palette ? GIMG_CHANNEL_RGBA : GIMG_CHANNEL_GRAY)
        << c.base;
    EXPECT_EQ(RasterBytes(raster), expected) << c.base;

    gimg_raster_destroy(raster);
    gimg_doc_destroy(doc);
    gimg_stream_destroy(s);
  }
}

TEST(PngDecode, Adam7IsAReorderingSoInterlacedDecodesLikeNonInterlaced) {
  // PNG 8.2: interlacing changes the transmission order of the pixels and
  // nothing else. The two members of each fixture pair hold the same samples,
  // so whatever the decoder produces for one it must produce for the other.
  // This needs no reference decoder to check.
  for (const SubByteCase & c : kSubByteCases) {
    GIMG_Stream * s_plain = nullptr;
    GIMG_Doc * doc_plain = nullptr;
    GIMG_Raster * plain = nullptr;
    ASSERT_TRUE(DecodeFixture(
        (std::string(c.base) + ".png").c_str(), &s_plain, &doc_plain, &plain));

    GIMG_Stream * s_int = nullptr;
    GIMG_Doc * doc_int = nullptr;
    GIMG_Raster * interlaced = nullptr;
    ASSERT_TRUE(DecodeFixture((std::string(c.base) + "_interlaced.png").c_str(),
        &s_int, &doc_int, &interlaced));

    EXPECT_TRUE(png_test::rasters_equal(plain, interlaced))
        << c.base << ": Adam7 pass reassembly disagrees with the "
        << "non-interlaced encoding of the same samples";

    gimg_raster_destroy(interlaced);
    gimg_doc_destroy(doc_int);
    gimg_stream_destroy(s_int);
    gimg_raster_destroy(plain);
    gimg_doc_destroy(doc_plain);
    gimg_stream_destroy(s_plain);
  }
}

TEST(PngDecode, SubByteInterlacedDecodesToTheExpectedSamples) {
  // The pair test above would pass if both halves were wrong in the same way;
  // this one pins the interlaced half to the spec-derived expected pixels.
  for (const SubByteCase & c : kSubByteCases) {
    std::vector<uint8_t> expected;
    ASSERT_TRUE(png_test::load_png_file(
        (std::string(c.base) + ".raw").c_str(), expected))
        << c.base << ".raw missing; run tests/data/png/generate.py";

    GIMG_Stream * s = nullptr;
    GIMG_Doc * doc = nullptr;
    GIMG_Raster * raster = nullptr;
    ASSERT_TRUE(DecodeFixture((std::string(c.base) + "_interlaced.png").c_str(),
        &s, &doc, &raster));

    EXPECT_EQ(RasterBytes(raster), expected) << c.base << " interlaced";

    gimg_raster_destroy(raster);
    gimg_doc_destroy(doc);
    gimg_stream_destroy(s);
  }
}

// ---------------------------------------------------------------------------
// zlib wrapper integrity (PNG 10.3, RFC 1950).
//
// PNG carries two independent checks on every compressed payload: the chunk
// CRC over the stored bytes, and the Adler-32 over the *uncompressed* bytes at
// the end of the zlib stream. The second is the only one that catches a stream
// which still inflates but to the wrong data, so skipping the two header bytes
// and four trailer bytes without reading them leaves half the check in place.
// The fixtures have correct chunk CRCs and differ from png_zlib_ok.png only in
// the zlib wrapper.
// ---------------------------------------------------------------------------

TEST(PngDecode, ZlibWrapperIsCheckedNotSkipped) {
  struct Case {
    const char * filename;
    GIMG_Result expect;
    const char * why;
  };
  const Case cases[] = {
      {"png_zlib_ok.png", GIMG_OK, "control: a correct zlib stream"},
      {"png_zlib_bad_adler.png", GIMG_ERR_CORRUPT,
          "Adler-32 of the wrong bytes (RFC 1950 2.2); DEFLATE alone accepts it"},
      {"png_zlib_bad_header.png", GIMG_ERR_FORMAT,
          "CMF/FLG not a multiple of 31 and method 9, not the 8 PNG 10.3 allows"},
      {"png_zlib_preset_dict.png", GIMG_ERR_FORMAT,
          "FDICT set, which PNG 10.3 forbids and which shifts the DEFLATE data"},
  };
  for (const Case & c : cases) {
    std::vector<uint8_t> buf;
    ASSERT_TRUE(png_test::load_png_file(c.filename, buf))
        << c.filename << " missing; run tests/data/png/generate.py";
    GIMG_Stream * s = nullptr;
    ASSERT_EQ(gimg_stream_create_memory(buf.data(), buf.size(), &s), GIMG_OK);
    GIMG_Doc * doc = nullptr;
    GIMG_Result r = gimg_doc_load(s, nullptr, nullptr, &doc);
    GIMG_Raster * raster = nullptr;
    if (r == GIMG_OK) {
      r = gimg_item_decode(gimg_doc_item(doc, 0), nullptr, &raster);
    }
    EXPECT_EQ(r, c.expect) << c.filename << ": " << c.why;
    if (raster) {
      gimg_raster_destroy(raster);
    }
    if (doc) {
      gimg_doc_destroy(doc);
    }
    gimg_stream_destroy(s);
  }
}

// ---------------------------------------------------------------------------
// A suggested palette on a truecolor image (PNG 11.2.2).
//
// PLTE is required for color type 3 and "shall not appear" for color types 0
// and 4, but for 2 and 6 it may appear as a suggested palette for a viewer that
// cannot display truecolor. A decoder that can display truecolor ignores it.
// The published conformance suite carries two such files (pp0n2c16, pp0n6a08).
// ---------------------------------------------------------------------------

TEST(PngDecode, SuggestedPaletteOnTruecolorIsAcceptedAndIgnored) {
  // The palette in the fixture does not contain the image's colors, so a
  // decoder that used it would produce different pixels from the twin that
  // carries no PLTE. Comparing the two needs no reference decoder.
  GIMG_Stream * s_with = nullptr;
  GIMG_Doc * doc_with = nullptr;
  GIMG_Raster * with_palette = nullptr;
  ASSERT_TRUE(DecodeFixture(
      "png_rgb_suggested_palette.png", &s_with, &doc_with, &with_palette));

  GIMG_Stream * s_without = nullptr;
  GIMG_Doc * doc_without = nullptr;
  GIMG_Raster * without_palette = nullptr;
  ASSERT_TRUE(DecodeFixture(
      "png_rgb_no_palette.png", &s_without, &doc_without, &without_palette));

  EXPECT_TRUE(png_test::rasters_equal(with_palette, without_palette))
      << "a suggested palette is advisory and must not change the pixels";

  gimg_raster_destroy(without_palette);
  gimg_doc_destroy(doc_without);
  gimg_stream_destroy(s_without);
  gimg_raster_destroy(with_palette);
  gimg_doc_destroy(doc_with);
  gimg_stream_destroy(s_with);

  // Color type 6 may carry one too.
  GIMG_Stream * s_rgba = nullptr;
  GIMG_Doc * doc_rgba = nullptr;
  GIMG_Raster * rgba = nullptr;
  EXPECT_TRUE(DecodeFixture(
      "png_rgba_suggested_palette.png", &s_rgba, &doc_rgba, &rgba));
  if (rgba) {
    gimg_raster_destroy(rgba);
    gimg_doc_destroy(doc_rgba);
    gimg_stream_destroy(s_rgba);
  }
}

TEST(PngDecode, PaletteOnGrayscaleIsRejected) {
  // PNG 11.2.2: "This chunk shall not appear for colour types 0 and 4." Some
  // decoders are more forgiving than the spec here - Pillow reads the file -
  // but a critical chunk where the spec forbids one is a malformed file, and
  // this library reports malformed files rather than guessing past them.
  std::vector<uint8_t> buf;
  ASSERT_TRUE(png_test::load_png_file("png_gray_forbidden_palette.png", buf))
      << "Run tests/data/png/generate.py";
  GIMG_Stream * s = nullptr;
  ASSERT_EQ(gimg_stream_create_memory(buf.data(), buf.size(), &s), GIMG_OK);
  GIMG_Doc * doc = nullptr;
  EXPECT_EQ(gimg_doc_load(s, nullptr, nullptr, &doc), GIMG_ERR_FORMAT);
  if (doc) {
    gimg_doc_destroy(doc);
  }
  gimg_stream_destroy(s);
}

// ---------------------------------------------------------------------------
// PNG Third Edition color chunks.
//
// cICP carries coding-independent code points (ITU-T H.273) and the Third
// Edition puts it ahead of sRGB, iCCP and gAMA+cHRM: where it appears, it says
// what the samples mean and the others do not get a say.
//
// GIMG_Color_Info can describe sRGB, Adobe RGB, linear and a plain gamma.
// CICP names far more - BT.2020, PQ, HLG, limited range - so only the
// combinations this model holds are translated. The rest leave the color
// unknown rather than being rounded to the nearest thing expressible, which
// would assert something about the pixels the file never said. Every one of
// these chunks is preserved on the way through regardless.
// ---------------------------------------------------------------------------

TEST(PngDecode, CicpOutranksTheOlderColorChunks) {
  // The fixture carries cICP naming the sRGB pair and a gAMA claiming 1.0.
  // Honoring the precedence and ignoring it give different answers.
  GIMG_Stream * s = nullptr;
  GIMG_Doc * doc = nullptr;
  GIMG_Raster * raster = nullptr;
  ASSERT_TRUE(DecodeFixture("png_cicp_srgb.png", &s, &doc, &raster));
  const GIMG_Color_Info * info = gimg_raster_color_info_const(raster);
  ASSERT_NE(info, nullptr);
  EXPECT_EQ(info->primaries, GIMG_PRIMARIES_SRGB);
  EXPECT_EQ(info->transfer, GIMG_TRANSFER_SRGB)
      << "cICP names the sRGB transfer; the gAMA of 1.0 must not win";
  gimg_raster_destroy(raster);
  gimg_doc_destroy(doc);
  gimg_stream_destroy(s);
}

TEST(PngDecode, ACicpThisColorModelCannotHoldLeavesItUnknown) {
  // BT.2020 primaries with the PQ transfer: a legal file, and nothing in
  // GIMG_Color_Info can say what it means. Reporting sRGB would be a lie.
  GIMG_Stream * s = nullptr;
  GIMG_Doc * doc = nullptr;
  GIMG_Raster * raster = nullptr;
  ASSERT_TRUE(DecodeFixture("png_cicp_bt2020_pq.png", &s, &doc, &raster));
  const GIMG_Color_Info * info = gimg_raster_color_info_const(raster);
  ASSERT_NE(info, nullptr);
  EXPECT_EQ(info->primaries, GIMG_PRIMARIES_UNKNOWN);
  EXPECT_EQ(info->transfer, GIMG_TRANSFER_UNKNOWN);
  gimg_raster_destroy(raster);
  gimg_doc_destroy(doc);
  gimg_stream_destroy(s);
}

TEST(PngDecode, ThirdEditionChunksSurviveARoundTrip) {
  // cICP, mDCv and cLLi are content the file came with. Whether or not this
  // library can act on them, saving must not drop them.
  struct Case {
    const char * filename;
    std::vector<uint32_t> expect_types;
  };
  const uint32_t kCicp = 0x63494350u;
  const uint32_t kMdcv = 0x6D444376u;
  const uint32_t kClli = 0x634C4C69u;
  const Case cases[] = {
      {"png_cicp_srgb.png", {kCicp}},
      {"png_cicp_bt2020_pq.png", {kCicp}},
      {"png_mdcv_clli.png", {kMdcv, kClli}},
  };
  for (const Case & c : cases) {
    std::vector<uint8_t> buf;
    ASSERT_TRUE(png_test::load_png_file(c.filename, buf)) << c.filename;
    GIMG_Stream * s = nullptr;
    ASSERT_EQ(gimg_stream_create_memory(buf.data(), buf.size(), &s), GIMG_OK);
    GIMG_Doc * doc = nullptr;
    ASSERT_EQ(gimg_doc_load(s, nullptr, nullptr, &doc), GIMG_OK) << c.filename;
    gimg_stream_destroy(s);

    GIMG_Stream * out_s = nullptr;
    ASSERT_EQ(gimg_stream_create_memory_output(&out_s), GIMG_OK);
    GIMG_Save_Options opts = {};
    opts.metadata_policy = GIMG_META_PRESERVE_ALL;
    GIMG_Save_Report report = {};
    ASSERT_EQ(gimg_doc_save(doc, out_s, "png", &opts, &report), GIMG_OK)
        << c.filename;
    const void * p = nullptr;
    size_t n = 0;
    gimg_stream_output_buffer(out_s, &p, &n);
    std::vector<uint8_t> saved(static_cast<const uint8_t *>(p),
        static_cast<const uint8_t *>(p) + n);
    gimg_stream_destroy(out_s);
    gimg_doc_destroy(doc);

    // Walk the chunks of the saved file looking for each expected type.
    for (uint32_t want : c.expect_types) {
      bool found = false;
      size_t i = 8;
      while (i + 8 <= saved.size()) {
        uint32_t len = (uint32_t)saved[i] << 24 | (uint32_t)saved[i + 1] << 16 |
            (uint32_t)saved[i + 2] << 8 | (uint32_t)saved[i + 3];
        uint32_t type = (uint32_t)saved[i + 4] << 24 |
            (uint32_t)saved[i + 5] << 16 | (uint32_t)saved[i + 6] << 8 |
            (uint32_t)saved[i + 7];
        if (type == want) {
          found = true;
          break;
        }
        i += 12u + (size_t)len;
      }
      EXPECT_TRUE(found) << c.filename << " lost chunk 0x" << std::hex << want;
    }
  }
}

// ---------------------------------------------------------------------------
// Filter types (PNG clause 9, Table 9.1)
//
// Table 9.1 defines filter types 0 through 4 and nothing else. A row whose
// filter byte is above 4 cannot be reconstructed: there is no predictor to
// invert. Treating it as None - which is what "ignore what you do not know"
// amounts to here - returns success for pixels no conforming decoder produces.
// libpng calls such a file a "bad adaptive filter value" and refuses it;
// Pillow calls it "unrecognized data stream contents" and refuses it too.
// ---------------------------------------------------------------------------

namespace {

/** Load a fixture and try to decode it; returns the result of the decode. */
GIMG_Result TryDecodeFixture(const char * filename) {
  std::vector<uint8_t> buf;
  if (!png_test::load_png_file(filename, buf)) {
    return GIMG_ERR_IO;
  }
  GIMG_Stream * s = nullptr;
  if (gimg_stream_create_memory(buf.data(), buf.size(), &s) != GIMG_OK) {
    return GIMG_ERR_INTERNAL;
  }
  GIMG_Doc * doc = nullptr;
  GIMG_Result r = gimg_doc_load(s, nullptr, nullptr, &doc);
  if (r != GIMG_OK) {
    gimg_stream_destroy(s);
    return r;
  }
  GIMG_Raster * raster = nullptr;
  r = gimg_item_decode(gimg_doc_item(doc, 0), nullptr, &raster);
  if (raster) {
    gimg_raster_destroy(raster);
  }
  gimg_doc_destroy(doc);
  gimg_stream_destroy(s);
  return r;
}

} // namespace

TEST(PngFilterType, AFilterTypeTableNineOneDoesNotDefineIsRefused) {
  EXPECT_EQ(TryDecodeFixture("png_bad_filter_type.png"), GIMG_ERR_CORRUPT);
}

TEST(PngFilterType, TheSameImageWithATypeThatExistsStillDecodes) {
  // The other half of the pair. A decoder that refused every row it had not
  // seen before would pass the test above and fail this one; filter type 1 is
  // Sub, the type a rejection of "anything above 4" must not reach.
  GIMG_Stream * s = nullptr;
  GIMG_Doc * doc = nullptr;
  GIMG_Raster * raster = nullptr;
  ASSERT_TRUE(DecodeFixture("png_good_filter_type.png", &s, &doc, &raster));
  // Row 0 is stored unfiltered; row 1 is Sub over {1,1,1,1}, so each sample is
  // the running sum of the ones before it (9.2).
  const std::vector<uint8_t> expected = {10, 20, 30, 40, 1, 2, 3, 4};
  EXPECT_EQ(RasterBytes(raster), expected);
  gimg_raster_destroy(raster);
  gimg_doc_destroy(doc);
  gimg_stream_destroy(s);
}

TEST(PngFilterType, TheCheckIsReachedOnTheInterlacedPathToo) {
  // Adam7 filters every pass as its own image (9.2), so the filter byte is
  // read in a second place and has to be checked in both.
  EXPECT_EQ(TryDecodeFixture("png_bad_filter_type_interlaced.png"),
      GIMG_ERR_CORRUPT);
}

// ---------------------------------------------------------------------------
// Chunks the spec fixes the shape of
//
// Several chunks have a length the spec states outright, and tRNS has both a
// length and a set of color types it may appear for. A chunk of the wrong
// length is not one whose meaning can be recovered - for color type 2 a tRNS
// is three 16-bit samples or it is nothing - and keeping it means writing a
// file that is malformed in the same way.
//
// Every stream below was put in front of libpng and Pillow before any of these
// tests was written. libpng accepts each with a warning naming the same defect
// (its policy is to warn and carry on); Pillow refuses most of them outright.
// Where this library is stricter than both it is because the spec says
// "shall", and the verdict is recorded with each case.
// ---------------------------------------------------------------------------

namespace {

/** Assemble a PNG from chunks, using the library's own CRC (5.5). */
class PngBuilder {
public:
  PngBuilder() {
    bytes_.assign(kSig, kSig + 8);
  }
  PngBuilder & chunk(const char * type, const std::vector<uint8_t> & data) {
    uint32_t t = ((uint32_t)(unsigned char)type[0] << 24) |
        ((uint32_t)(unsigned char)type[1] << 16) |
        ((uint32_t)(unsigned char)type[2] << 8) |
        (uint32_t)(unsigned char)type[3];
    GIMG_Stream * s = nullptr;
    if (gimg_stream_create_memory_output(&s) != GIMG_OK) {
      return *this;
    }
    if (gimg_png_write_chunk(s, t, data.empty() ? nullptr : data.data(),
            data.size()) == GIMG_OK) {
      const void * p = nullptr;
      size_t n = 0;
      gimg_stream_output_buffer(s, &p, &n);
      const auto * b = static_cast<const uint8_t *>(p);
      bytes_.insert(bytes_.end(), b, b + n);
    }
    gimg_stream_destroy(s);
    return *this;
  }
  PngBuilder & ihdr(uint32_t w, uint32_t h, uint8_t depth, uint8_t ct) {
    std::vector<uint8_t> d = {(uint8_t)(w >> 24), (uint8_t)(w >> 16),
        (uint8_t)(w >> 8), (uint8_t)w, (uint8_t)(h >> 24), (uint8_t)(h >> 16),
        (uint8_t)(h >> 8), (uint8_t)h, depth, ct, 0, 0, 0};
    return chunk("IHDR", d);
  }
  const std::vector<uint8_t> & bytes() const {
    return bytes_;
  }

private:
  static constexpr uint8_t kSig[8] = {0x89, 'P', 'N', 'G', '\r', '\n', 0x1A,
      '\n'};
  std::vector<uint8_t> bytes_;
};
constexpr uint8_t PngBuilder::kSig[8];

/** Try to load and decode a stream; return whatever the load or decode said. */
GIMG_Result TryDecodeBytes(const std::vector<uint8_t> & png) {
  GIMG_Stream * s = nullptr;
  if (gimg_stream_create_memory(png.data(), png.size(), &s) != GIMG_OK) {
    return GIMG_ERR_INTERNAL;
  }
  GIMG_Doc * doc = nullptr;
  GIMG_Result r = gimg_doc_load(s, nullptr, nullptr, &doc);
  if (r != GIMG_OK) {
    gimg_stream_destroy(s);
    return r;
  }
  GIMG_Raster * raster = nullptr;
  r = gimg_item_decode(gimg_doc_item(doc, 0), nullptr, &raster);
  if (raster) {
    gimg_raster_destroy(raster);
  }
  gimg_doc_destroy(doc);
  gimg_stream_destroy(s);
  return r;
}

/**
 * A zlib stream (RFC 1950) holding @a h filter-None scanlines of @a w zero
 * bytes, as a single stored DEFLATE block. Stored rather than compressed so
 * the test builds its own input without depending on an encoder to do it.
 */
std::vector<uint8_t> GrayIdatPayload(uint32_t w, uint32_t h) {
  std::vector<uint8_t> raw;
  for (uint32_t y = 0; y < h; y++) {
    raw.push_back(0); // filter type None (9.2)
    raw.insert(raw.end(), w, 0);
  }
  std::vector<uint8_t> out = {0x78, 0x01}; // CM 8, CINFO 7, FCHECK (RFC 1950)
  size_t off = 0;
  do {
    size_t n = raw.size() - off;
    if (n > 65535u) {
      n = 65535u;
    }
    const bool last = (off + n == raw.size());
    out.push_back(last ? 1 : 0); // BFINAL, BTYPE 00 stored (RFC 1951 3.2.4)
    out.push_back((uint8_t)(n & 0xFF));
    out.push_back((uint8_t)(n >> 8));
    out.push_back((uint8_t)(~n & 0xFF));
    out.push_back((uint8_t)((~n >> 8) & 0xFF));
    out.insert(out.end(), raw.begin() + (long)off, raw.begin() + (long)(off + n));
    off += n;
  } while (off < raw.size());
  uint32_t s1 = 1, s2 = 0;
  for (uint8_t v : raw) {
    s1 = (s1 + v) % 65521u;
    s2 = (s2 + s1) % 65521u;
  }
  uint32_t adler = (s2 << 16) | s1;
  out.push_back((uint8_t)(adler >> 24));
  out.push_back((uint8_t)(adler >> 16));
  out.push_back((uint8_t)(adler >> 8));
  out.push_back((uint8_t)adler);
  return out;
}

} // namespace

TEST(PngChunkShape, TransparencyOfTheWrongLengthIsRefused) {
  // 11.3.2.1: two bytes for color type 0, six for color type 2.
  // libpng: "tRNS: invalid" (warns). Pillow: refuses.
  {
    PngBuilder b;
    b.ihdr(4, 4, 8, 0).chunk("tRNS", {0x00});
    b.chunk("IDAT", GrayIdatPayload(4, 4)).chunk("IEND", {});
    EXPECT_EQ(TryDecodeBytes(b.bytes()), GIMG_ERR_FORMAT) << "color type 0";
  }
  {
    PngBuilder b;
    b.ihdr(4, 4, 8, 0).chunk("tRNS", {0x00, 0x01, 0x02});
    b.chunk("IDAT", GrayIdatPayload(4, 4)).chunk("IEND", {});
    EXPECT_EQ(TryDecodeBytes(b.bytes()), GIMG_ERR_FORMAT) << "three bytes";
  }
  {
    // The control: two bytes is the right length and must still load.
    PngBuilder b;
    b.ihdr(4, 4, 8, 0).chunk("tRNS", {0x00, 0x01});
    b.chunk("IDAT", GrayIdatPayload(4, 4)).chunk("IEND", {});
    EXPECT_EQ(TryDecodeBytes(b.bytes()), GIMG_OK);
  }
}

TEST(PngChunkShape, TransparencyOnAColorTypeThatHasAlphaIsRefused) {
  // 11.3.2.1: tRNS "shall not appear" for color types 4 and 6. A decoder that
  // kept it would have two sources of transparency and no rule for which wins.
  // libpng warns; Pillow accepts. The spec is explicit, so this is refused.
  PngBuilder b;
  b.ihdr(4, 4, 8, 4).chunk("tRNS", {0x00, 0x01});
  b.chunk("IDAT", GrayIdatPayload(4 * 2, 4)).chunk("IEND", {});
  EXPECT_EQ(TryDecodeBytes(b.bytes()), GIMG_ERR_FORMAT);
}

TEST(PngChunkShape, AncillaryChunksOfAFixedLengthAreChecked) {
  // Each of these has a length the spec states outright. libpng warns on every
  // one; Pillow refuses gAMA, cHRM, sRGB and pHYs.
  struct Case {
    const char * type;
    size_t wrong_len;
    const char * clause;
  };
  const Case cases[] = {
      {"gAMA", 2, "11.3.2.2: four bytes"},
      {"cHRM", 31, "11.3.2.1: 32 bytes"},
      {"sRGB", 0, "11.3.2.5: one byte"},
      {"pHYs", 8, "11.3.4.3: nine bytes"},
      {"tIME", 6, "11.3.5: seven bytes"},
      {"cICP", 3, "four code points"},
  };
  for (const Case & c : cases) {
    char t[5] = {c.type[0], c.type[1], c.type[2], c.type[3], 0};
    PngBuilder b;
    b.ihdr(4, 4, 8, 0);
    b.chunk(t, std::vector<uint8_t>(c.wrong_len, 0));
    b.chunk("IDAT", GrayIdatPayload(4, 4)).chunk("IEND", {});
    EXPECT_EQ(TryDecodeBytes(b.bytes()), GIMG_ERR_FORMAT) << c.clause;
  }
}

TEST(PngChunkShape, ThoseSameChunksAtTheirRightLengthStillLoad) {
  // The other half. A check that refused these lengths as well would pass
  // every case above and be worthless.
  struct Case {
    const char * type;
    size_t len;
  };
  const Case cases[] = {{"gAMA", 4}, {"cHRM", 32}, {"sRGB", 1}, {"pHYs", 9},
      {"tIME", 7}, {"cICP", 4}};
  for (const Case & c : cases) {
    char t[5] = {c.type[0], c.type[1], c.type[2], c.type[3], 0};
    PngBuilder b;
    b.ihdr(4, 4, 8, 0);
    b.chunk(t, std::vector<uint8_t>(c.len, 0));
    b.chunk("IDAT", GrayIdatPayload(4, 4)).chunk("IEND", {});
    EXPECT_EQ(TryDecodeBytes(b.bytes()), GIMG_OK) << c.type;
  }
}

// ---------------------------------------------------------------------------
// APNG frame bounds
//
// The APNG specification requires a frame to lie inside the canvas the IHDR
// describes. It is not an advisory constraint: compositing writes the frame
// into the canvas at x_offset, y_offset, so a frame declared past the edge is
// a heap write past the end of the canvas buffer. This library used to do
// exactly that, and AddressSanitizer reported it as
//
//   heap-buffer-overflow ... WRITE of size 1
//   in gimg_png_apng_blend_frame src/codec/png/png_decode.c
//
// reachable from any file that declared one. Pillow refuses such a file
// ("APNG contains invalid frames").
// ---------------------------------------------------------------------------

namespace {

/** Load, then decode every item; returns the first non-OK result. */
GIMG_Result DecodeAllItems(const char * filename) {
  std::vector<uint8_t> buf;
  if (!png_test::load_png_file(filename, buf)) {
    return GIMG_ERR_IO;
  }
  GIMG_Stream * s = nullptr;
  if (gimg_stream_create_memory(buf.data(), buf.size(), &s) != GIMG_OK) {
    return GIMG_ERR_INTERNAL;
  }
  GIMG_Doc * doc = nullptr;
  GIMG_Result r = gimg_doc_load(s, nullptr, nullptr, &doc);
  if (r != GIMG_OK) {
    gimg_stream_destroy(s);
    return r;
  }
  size_t n = gimg_doc_item_count(doc);
  for (size_t i = 0; i < n && r == GIMG_OK; i++) {
    GIMG_Raster * raster = nullptr;
    r = gimg_item_decode(gimg_doc_item(doc, i), nullptr, &raster);
    if (raster) {
      gimg_raster_destroy(raster);
    }
  }
  gimg_doc_destroy(doc);
  gimg_stream_destroy(s);
  return r;
}

} // namespace

TEST(PngApngBounds, AFrameReachingPastTheCanvasIsRefused) {
  // An 8x8 frame at (4,4) on an 8x8 canvas: four pixels past each edge.
  EXPECT_EQ(DecodeAllItems("png_apng_frame_outside_canvas.png"),
      GIMG_ERR_FORMAT);
}

TEST(PngApngBounds, AFrameOfZeroSizeIsRefused) {
  EXPECT_EQ(DecodeAllItems("png_apng_frame_zero_size.png"), GIMG_ERR_FORMAT);
}

TEST(PngApngBounds, AnOffsetFrameThatFitsStillDecodes) {
  // The control. A 4x4 frame at (4,4) fits an 8x8 canvas exactly, and a check
  // that refused every offset frame would pass the two tests above and make
  // the whole of APNG's frame placement unusable.
  EXPECT_EQ(DecodeAllItems("png_apng_frame_inside_canvas.png"), GIMG_OK);

  // And the second frame really is composited where it was asked to be: the
  // canvas is red, the frame is green, so the quadrant at (4,4) is green and
  // the pixel at (0,0) is still red.
  std::vector<uint8_t> buf;
  ASSERT_TRUE(
      png_test::load_png_file("png_apng_frame_inside_canvas.png", buf));
  GIMG_Stream * s = nullptr;
  ASSERT_EQ(gimg_stream_create_memory(buf.data(), buf.size(), &s), GIMG_OK);
  GIMG_Doc * doc = nullptr;
  ASSERT_EQ(gimg_doc_load(s, nullptr, nullptr, &doc), GIMG_OK);
  ASSERT_EQ(gimg_doc_item_count(doc), 2u);
  GIMG_Raster * raster = nullptr;
  ASSERT_EQ(gimg_item_decode(gimg_doc_item(doc, 1), nullptr, &raster), GIMG_OK);
  size_t stride = gimg_raster_stride_bytes(raster);
  const auto * px =
      static_cast<const unsigned char *>(gimg_raster_pixels_const(raster));
  EXPECT_EQ(px[0], 255) << "(0,0) is outside the frame and stays red";
  EXPECT_EQ(px[1], 0);
  const unsigned char * at44 = px + 4u * stride + 4u * 4u;
  EXPECT_EQ(at44[0], 0) << "(4,4) is inside the frame and is green";
  EXPECT_EQ(at44[1], 255);
  gimg_raster_destroy(raster);
  gimg_doc_destroy(doc);
  gimg_stream_destroy(s);
}

// ---------------------------------------------------------------------------
// Text chunks (PNG 11.3.3)
//
// tEXt carries its text directly, zTXt carries it deflated, and iTXt carries
// it either way with a language tag and a translated keyword in between. All
// three feed the document's description when their keyword is "Description" or
// "Comment".
//
// None of this was reached by a test: the zTXt and iTXt branches of
// gimg_png_text_chunk_decode were entirely uncovered, including the handling
// of a compression method the format does not define - which the reference
// documentation described, incorrectly for one of the two.
//
// A text chunk that cannot be decoded is skipped rather than failing the load,
// which is what libpng does with one. The image is not at fault.
// ---------------------------------------------------------------------------

namespace {

/** zlib-wrap a payload the way a text chunk carries one (RFC 1950). */
std::vector<uint8_t> Deflate(const std::string & text) {
  std::vector<uint8_t> raw(text.begin(), text.end());
  std::vector<uint8_t> out = {0x78, 0x01};
  size_t off = 0;
  do {
    size_t n = raw.size() - off;
    if (n > 65535u) {
      n = 65535u;
    }
    out.push_back((off + n == raw.size()) ? 1 : 0);
    out.push_back((uint8_t)(n & 0xFF));
    out.push_back((uint8_t)(n >> 8));
    out.push_back((uint8_t)(~n & 0xFF));
    out.push_back((uint8_t)((~n >> 8) & 0xFF));
    out.insert(out.end(), raw.begin() + (long)off, raw.begin() + (long)(off + n));
    off += n;
  } while (off < raw.size());
  uint32_t s1 = 1, s2 = 0;
  for (uint8_t v : raw) {
    s1 = (s1 + v) % 65521u;
    s2 = (s2 + s1) % 65521u;
  }
  uint32_t adler = (s2 << 16) | s1;
  out.push_back((uint8_t)(adler >> 24));
  out.push_back((uint8_t)(adler >> 16));
  out.push_back((uint8_t)(adler >> 8));
  out.push_back((uint8_t)adler);
  return out;
}

void Append(std::vector<uint8_t> & v, const std::string & s) {
  v.insert(v.end(), s.begin(), s.end());
}

/** Run one payload through the decoder; returns the result and the text. */
GIMG_Result DecodeText(gimg_png_chunk_type_t type,
    const std::vector<uint8_t> & payload, std::string * out) {
  size_t kw_len = 0;
  char * text = nullptr;
  GIMG_Result r = gimg_png_text_chunk_decode(
      type, payload.data(), payload.size(), gimg_allocator_default(), &kw_len,
      &text);
  if (r == GIMG_OK && text) {
    *out = text;
  }
  if (text) {
    gimg_free(gimg_allocator_default(), text);
  }
  return r;
}

} // namespace

TEST(PngTextChunk, PlainTextComesBackAsItWasWritten) {
  std::vector<uint8_t> p;
  Append(p, "Description");
  p.push_back(0);
  Append(p, "a caption");
  std::string got;
  EXPECT_EQ(DecodeText(GIMG_PNG_tEXt, p, &got), GIMG_OK);
  EXPECT_EQ(got, "a caption");
}

TEST(PngTextChunk, CompressedTextIsInflated) {
  std::vector<uint8_t> p;
  Append(p, "Description");
  p.push_back(0);
  p.push_back(0); // compression method 0, the only one 11.3.3 defines
  std::vector<uint8_t> z = Deflate("a longer caption, deflated");
  p.insert(p.end(), z.begin(), z.end());
  std::string got;
  EXPECT_EQ(DecodeText(GIMG_PNG_zTXt, p, &got), GIMG_OK);
  EXPECT_EQ(got, "a longer caption, deflated");
}

TEST(PngTextChunk, InternationalTextWorksBothCompressedAndNot) {
  // iTXt: keyword, compression flag, compression method, language tag,
  // translated keyword, then the text (11.3.3).
  for (int compressed = 0; compressed <= 1; compressed++) {
    std::vector<uint8_t> p;
    Append(p, "Description");
    p.push_back(0);
    p.push_back((uint8_t)compressed);
    p.push_back(0); // compression method
    Append(p, "en");
    p.push_back(0);
    Append(p, "Beskrivelse");
    p.push_back(0);
    const std::string text = "a caption with an accent: cafe";
    if (compressed) {
      std::vector<uint8_t> z = Deflate(text);
      p.insert(p.end(), z.begin(), z.end());
    }
    else {
      Append(p, text);
    }
    std::string got;
    EXPECT_EQ(DecodeText(GIMG_PNG_iTXt, p, &got), GIMG_OK)
        << "compressed=" << compressed;
    EXPECT_EQ(got, text) << "compressed=" << compressed;
  }
}

TEST(PngTextChunk, ACompressionMethodTheFormatDoesNotDefineIsRefused) {
  // 11.3.3 defines method 0 and nothing else. Both chunk types say the same
  // thing about the same byte; they used to disagree.
  {
    std::vector<uint8_t> p;
    Append(p, "Description");
    p.push_back(0);
    p.push_back(1); // not a compression method
    std::vector<uint8_t> z = Deflate("text");
    p.insert(p.end(), z.begin(), z.end());
    std::string got;
    EXPECT_EQ(DecodeText(GIMG_PNG_zTXt, p, &got), GIMG_ERR_FORMAT);
  }
  {
    std::vector<uint8_t> p;
    Append(p, "Description");
    p.push_back(0);
    p.push_back(1); // compressed
    p.push_back(1); // not a compression method
    Append(p, "en");
    p.push_back(0);
    p.push_back(0);
    std::vector<uint8_t> z = Deflate("text");
    p.insert(p.end(), z.begin(), z.end());
    std::string got;
    EXPECT_EQ(DecodeText(GIMG_PNG_iTXt, p, &got), GIMG_ERR_FORMAT);
  }
}

TEST(PngTextChunk, TextWhoseChecksumDoesNotMatchIsRefused) {
  // The Adler-32 at the end of a zlib stream (10.3, RFC 1950) is checked for a
  // text chunk as it is for image data - it is the only check that catches
  // bytes which still inflate but to something else.
  std::vector<uint8_t> p;
  Append(p, "Description");
  p.push_back(0);
  p.push_back(0);
  std::vector<uint8_t> z = Deflate("a caption");
  z[z.size() - 1] ^= 0xFF; // damage the checksum only
  p.insert(p.end(), z.begin(), z.end());
  std::string got;
  EXPECT_EQ(DecodeText(GIMG_PNG_zTXt, p, &got), GIMG_ERR_CORRUPT);
}

TEST(PngTextChunk, AKeywordWithNoTerminatorIsRefused) {
  std::vector<uint8_t> p;
  Append(p, "Description"); // no NUL, so there is no text after it
  std::string got;
  EXPECT_EQ(DecodeText(GIMG_PNG_tEXt, p, &got), GIMG_ERR_FORMAT);
}

TEST(PngTextChunk, ACompressedDescriptionReachesTheDocument) {
  // End to end: the chunk in a file, the description on the loaded document.
  std::vector<uint8_t> p;
  Append(p, "Description");
  p.push_back(0);
  p.push_back(0);
  std::vector<uint8_t> z = Deflate("what the picture shows");
  p.insert(p.end(), z.begin(), z.end());

  PngBuilder b;
  b.ihdr(4, 4, 8, 0).chunk("zTXt", p);
  b.chunk("IDAT", GrayIdatPayload(4, 4)).chunk("IEND", {});

  GIMG_Stream * s = nullptr;
  ASSERT_EQ(gimg_stream_create_memory(b.bytes().data(), b.bytes().size(), &s),
      GIMG_OK);
  GIMG_Doc * doc = nullptr;
  ASSERT_EQ(gimg_doc_load(s, nullptr, nullptr, &doc), GIMG_OK);
  GIMG_Meta_Common * meta = gimg_doc_meta_common(doc);
  ASSERT_NE(meta, nullptr);
  const char * d = gimg_meta_common_description(meta);
  ASSERT_NE(d, nullptr);
  EXPECT_STREQ(d, "what the picture shows");
  gimg_doc_destroy(doc);
  gimg_stream_destroy(s);
}

TEST(PngTextChunk, ABrokenTextChunkDoesNotStopTheImageLoading) {
  // libpng skips a text chunk it cannot read and carries on; so does this.
  std::vector<uint8_t> p;
  Append(p, "Description");
  p.push_back(0);
  p.push_back(1); // not a compression method
  std::vector<uint8_t> z = Deflate("text");
  p.insert(p.end(), z.begin(), z.end());

  PngBuilder b;
  b.ihdr(4, 4, 8, 0).chunk("zTXt", p);
  b.chunk("IDAT", GrayIdatPayload(4, 4)).chunk("IEND", {});
  EXPECT_EQ(TryDecodeBytes(b.bytes()), GIMG_OK);
}

// ---------------------------------------------------------------------------
// Physical pixel dimensions (PNG 11.3.4.3)
//
// pHYs states pixels per meter; the common metadata carries dots per inch,
// which is what JFIF and Exif state and what the JPEG codec already reads and
// writes. Until this was wired up a resolution survived a JPEG round trip and
// was lost the moment the image became a PNG.
// ---------------------------------------------------------------------------

TEST(PngPhys, DotsPerInchAndPixelsPerMeterConvertBothWays) {
  // An inch is exactly 0.0254 m. 300 dpi is 11811 pixels per meter, which is
  // the value every other tool writes for 300 dpi - Pillow reads this file
  // back as 299.9994, so agreeing on the integer matters more than agreeing
  // on the real number.
  EXPECT_EQ(gimg_png_dpi_to_pixels_per_meter(300u), 11811u);
  EXPECT_EQ(gimg_png_dpi_to_pixels_per_meter(72u), 2835u);
  EXPECT_EQ(gimg_png_dpi_to_pixels_per_meter(96u), 3780u);

  EXPECT_EQ(gimg_png_pixels_per_meter_to_dpi(11811u), 300u);
  EXPECT_EQ(gimg_png_pixels_per_meter_to_dpi(2835u), 72u);
  EXPECT_EQ(gimg_png_pixels_per_meter_to_dpi(3780u), 96u);

  // Zero is how both sides spell "not stated" and must not become one.
  EXPECT_EQ(gimg_png_dpi_to_pixels_per_meter(0u), 0u);
  EXPECT_EQ(gimg_png_pixels_per_meter_to_dpi(0u), 0u);

  // Every ordinary resolution survives the trip; the conversion is not lossy
  // in the range anyone uses.
  for (uint32_t dpi = 1; dpi <= 1200; dpi++) {
    EXPECT_EQ(
        gimg_png_pixels_per_meter_to_dpi(gimg_png_dpi_to_pixels_per_meter(dpi)),
        dpi)
        << "dpi " << dpi;
  }
  // And a value large enough to overflow a 32-bit intermediate saturates
  // rather than wrapping: dpi * 5000 leaves the range near 859,000.
  EXPECT_EQ(gimg_png_dpi_to_pixels_per_meter(UINT32_MAX), UINT32_MAX);
}

namespace {

/** A 4x4 gray PNG carrying one pHYs with the given values. */
std::vector<uint8_t> PngWithPhys(uint32_t x_ppm, uint32_t y_ppm, uint8_t unit) {
  std::vector<uint8_t> phys = {(uint8_t)(x_ppm >> 24), (uint8_t)(x_ppm >> 16),
      (uint8_t)(x_ppm >> 8), (uint8_t)x_ppm, (uint8_t)(y_ppm >> 24),
      (uint8_t)(y_ppm >> 16), (uint8_t)(y_ppm >> 8), (uint8_t)y_ppm, unit};
  PngBuilder b;
  b.ihdr(4, 4, 8, 0).chunk("pHYs", phys);
  b.chunk("IDAT", GrayIdatPayload(4, 4)).chunk("IEND", {});
  return b.bytes();
}

/** Load bytes and report the document's dpi. */
void LoadDpi(const std::vector<uint8_t> & png, uint32_t * x, uint32_t * y) {
  *x = *y = 0;
  GIMG_Stream * s = nullptr;
  ASSERT_EQ(gimg_stream_create_memory(png.data(), png.size(), &s), GIMG_OK);
  GIMG_Doc * doc = nullptr;
  ASSERT_EQ(gimg_doc_load(s, nullptr, nullptr, &doc), GIMG_OK);
  GIMG_Meta_Common * m = gimg_doc_meta_common(doc);
  if (m) {
    gimg_meta_common_dpi(m, x, y);
  }
  gimg_doc_destroy(doc);
  gimg_stream_destroy(s);
}

} // namespace

TEST(PngPhys, AResolutionInMetersBecomesTheDocumentsDpi) {
  uint32_t x = 0, y = 0;
  LoadDpi(PngWithPhys(11811u, 11811u, 1u), &x, &y);
  EXPECT_EQ(x, 300u);
  EXPECT_EQ(y, 300u);
}

TEST(PngPhys, AnAspectRatioIsNotAResolution) {
  // Unit specifier 0 says how the two axes relate, not how big a pixel is
  // (11.3.4.3), so there is no dpi in it to report.
  uint32_t x = 0, y = 0;
  LoadDpi(PngWithPhys(2u, 1u, 0u), &x, &y);
  EXPECT_EQ(x, 0u);
  EXPECT_EQ(y, 0u);
}

TEST(PngPhys, NonSquarePixelsKeepTheirTwoAxesApart) {
  uint32_t x = 0, y = 0;
  LoadDpi(PngWithPhys(11811u, 5906u, 1u), &x, &y);
  EXPECT_EQ(x, 300u);
  EXPECT_EQ(y, 150u);
}

TEST(PngPhys, ADpiTheDocumentCarriesIsWrittenOut) {
  // A document that never came from a PNG - so nothing preserved a pHYs - but
  // which knows its resolution. This is the JPEG-to-PNG case.
  GIMG_Raster * raster = nullptr;
  ASSERT_EQ(gimg_raster_create(4, 4, &GIMG_PIXEL_GRAY8, GIMG_RASTER_OWNED,
                nullptr, 0, &raster),
      GIMG_OK);
  memset(gimg_raster_pixels(raster), 128, 16);
  GIMG_Doc * doc = nullptr;
  ASSERT_EQ(gimg_doc_from_raster(raster, &doc), GIMG_OK);
  gimg_raster_destroy(raster);
  GIMG_Meta_Common * meta = nullptr;
  ASSERT_EQ(gimg_doc_ensure_meta_common(doc, &meta), GIMG_OK);
  gimg_meta_common_set_dpi(meta, 300u, 300u);

  for (GIMG_Meta_Policy policy :
      {GIMG_META_PRESERVE_ALL, GIMG_META_KEEP_COMMON_ONLY}) {
    GIMG_Stream * out_s = nullptr;
    ASSERT_EQ(gimg_stream_create_memory_output(&out_s), GIMG_OK);
    GIMG_Save_Options opts = {};
    opts.metadata_policy = policy;
    GIMG_Save_Report report = {};
    ASSERT_EQ(gimg_doc_save(doc, out_s, "png", &opts, &report), GIMG_OK);
    const void * p = nullptr;
    size_t n = 0;
    gimg_stream_output_buffer(out_s, &p, &n);
    std::vector<uint8_t> saved(static_cast<const uint8_t *>(p),
        static_cast<const uint8_t *>(p) + n);
    gimg_stream_destroy(out_s);

    uint32_t x = 0, y = 0;
    LoadDpi(saved, &x, &y);
    EXPECT_EQ(x, 300u) << "policy " << (int)policy;
    EXPECT_EQ(y, 300u) << "policy " << (int)policy;
  }
  gimg_doc_destroy(doc);
}

TEST(PngPhys, TheChunkTheFileCameWithIsTheOneWrittenBack) {
  // Only one pHYs may appear (Table 5.3 allows one). The file's own is what
  // was actually there; the metadata copy is a fallback for a document that
  // arrived without one.
  std::vector<uint8_t> png = PngWithPhys(11811u, 11811u, 1u);
  GIMG_Stream * s = nullptr;
  ASSERT_EQ(gimg_stream_create_memory(png.data(), png.size(), &s), GIMG_OK);
  GIMG_Doc * doc = nullptr;
  ASSERT_EQ(gimg_doc_load(s, nullptr, nullptr, &doc), GIMG_OK);
  gimg_stream_destroy(s);

  GIMG_Stream * out_s = nullptr;
  ASSERT_EQ(gimg_stream_create_memory_output(&out_s), GIMG_OK);
  GIMG_Save_Options opts = {};
  opts.metadata_policy = GIMG_META_PRESERVE_ALL;
  GIMG_Save_Report report = {};
  ASSERT_EQ(gimg_doc_save(doc, out_s, "png", &opts, &report), GIMG_OK);
  const void * p = nullptr;
  size_t n = 0;
  gimg_stream_output_buffer(out_s, &p, &n);
  std::vector<uint8_t> saved(static_cast<const uint8_t *>(p),
      static_cast<const uint8_t *>(p) + n);
  gimg_stream_destroy(out_s);
  gimg_doc_destroy(doc);

  int count = 0;
  size_t i = 8;
  while (i + 8 <= saved.size()) {
    uint32_t len = ((uint32_t)saved[i] << 24) | ((uint32_t)saved[i + 1] << 16) |
        ((uint32_t)saved[i + 2] << 8) | (uint32_t)saved[i + 3];
    if (memcmp(&saved[i + 4], "pHYs", 4) == 0) {
      count++;
    }
    if (i + 12 + (size_t)len > saved.size()) {
      break;
    }
    i += 12 + (size_t)len;
  }
  EXPECT_EQ(count, 1) << "one pHYs, not the file's and the metadata's as well";
}

TEST(PngPhys, AResolutionSurvivesTheTripFromJpeg) {
  // The case this was for. A JPEG states its resolution in a JFIF APP0 and the
  // JPEG codec already reads it into the common metadata; before pHYs was
  // wired up, saving that document as a PNG dropped it on the floor.
  //
  // The fixture is written by Pillow at 300 dpi, so the density on the way in
  // is a real one and not this project's idea of one.
  std::vector<uint8_t> jpeg;
  ASSERT_TRUE(png_test::load_png_file("jpeg_300dpi_8x8.jpg", jpeg))
      << "run tests/data/png/generate.py";

  GIMG_Stream * s = nullptr;
  ASSERT_EQ(gimg_stream_create_memory(jpeg.data(), jpeg.size(), &s), GIMG_OK);
  GIMG_Doc * doc = nullptr;
  ASSERT_EQ(gimg_doc_load(s, nullptr, nullptr, &doc), GIMG_OK);
  gimg_stream_destroy(s);
  GIMG_Meta_Common * meta = gimg_doc_meta_common(doc);
  ASSERT_NE(meta, nullptr);
  uint32_t jx = 0, jy = 0;
  gimg_meta_common_dpi(meta, &jx, &jy);
  ASSERT_EQ(jx, 300u) << "the JPEG half of this is the other suite's business";

  GIMG_Stream * out_s = nullptr;
  ASSERT_EQ(gimg_stream_create_memory_output(&out_s), GIMG_OK);
  GIMG_Save_Options opts = {};
  opts.metadata_policy = GIMG_META_PRESERVE_ALL;
  GIMG_Save_Report report = {};
  ASSERT_EQ(gimg_doc_save(doc, out_s, "png", &opts, &report), GIMG_OK);
  const void * p = nullptr;
  size_t n = 0;
  gimg_stream_output_buffer(out_s, &p, &n);
  std::vector<uint8_t> png(static_cast<const uint8_t *>(p),
      static_cast<const uint8_t *>(p) + n);
  gimg_stream_destroy(out_s);
  gimg_doc_destroy(doc);

  uint32_t px = 0, py = 0;
  LoadDpi(png, &px, &py);
  EXPECT_EQ(px, 300u) << "300 dpi went in as JPEG and must come out as PNG";
  EXPECT_EQ(py, 300u);
}
